import fs from 'node:fs';
import path from 'node:path';
const root=path.resolve(new URL('..', import.meta.url).pathname);
const html=fs.readFileSync(path.join(root,'mapa/index.html'),'utf8');
const js=fs.readFileSync(path.join(root,'assets/js/features/mapa/workspace.js'),'utf8');
const css=fs.readFileSync(path.join(root,'assets/css/features/mapa/app.css'),'utf8');
const app=fs.readFileSync(path.join(root,'assets/js/features/mapa/app.js'),'utf8');
const runtime=fs.readFileSync(path.join(root,'assets/js/core/ui.js'),'utf8');
const must=(cond,msg)=>{if(!cond){console.error('FAIL:',msg);process.exitCode=1}else console.log('OK:',msg)};
must(html.includes('geo-workspace panel-collapsed'),'workspace inicia sem painel');
must(html.includes('geo-sidepanel collapsed'),'painel inicia recolhido');
must(html.includes('/assets/css/features/mapa/app.css'),'CSS novo carregado');
must(html.includes('workspace.js'),'JS novo carregado');
must(css.includes('.sidepanel-tabs-four{display:none!important}'),'abas laterais antigas ficam ocultas');
must(css.includes('#sidePanelFloatToggle{display:none!important}'),'toggle flutuante antigo fica oculto');
must(js.includes("openPanel('project'"),'Salvar abre painel Projeto');
must(js.includes("openPanel('layers'"),'Camadas abre painel Camadas');
must(js.includes("['glebas', 'Glebas'"),'Glebas está no menu rápido');
must(!js.includes("['tools', 'Ferramentas'"),'atalho redundante Ferramentas foi removido do menu rápido');
must(js.includes('Adicionar camada'),'painel Camadas oferece Adicionar camada');
must(js.includes("color: '#dc2626'"),'CAR pesquisado usa destaque vermelho');
must(js.includes('geoserver.car.gov.br/geoserver/sicar/ows'),'busca CAR usa geometria pública SICAR');
must(js.includes('svMapSearchSubmit'),'busca superior possui botão de pesquisa clicável');
must(js.includes('looksLikeCar') && js.includes('formatCarDotted'),'busca CAR aceita código compacto ou formatado com pontos');
must(js.includes('runUnifiedSearch'),'lupa e Enter usam busca unificada');
must(runtime.includes("group('Camadas',[layers])"),'grupo Camadas superior não possui mais Adicionar');
must(!runtime.includes("const add=proxyFrom($('toggleLayersPanel'),'Adicionar'"),'atalho superior Adicionar foi removido');
must(css.includes('sv-context-launcher::after') && css.includes('content:none!important'),'Glebas aparece somente como ícone com tooltip');
must(js.includes("if (!isCar(car)) return false"),'consulta CAR só intercepta formato válido');
must(app.includes("Informe o nome do projeto."),'salvamento exige nome do projeto');
if(process.exitCode) process.exit(process.exitCode);
